import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation with methods to add items and check for membership.
    Uses optimal bit array size and number of hash functions calculated based on 
    expected items and false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.num_bits = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._optimal_num_hashes(self.num_bits, expected_items)
        self.bit_array = [0] * (self.num_bits // 8 + 1)

    def add(self, item: str) -> None:
        for i in range(self.num_hashes):
            hash_value = self._hash(item, i)
            self.bit_array[hash_value // 8] |= 1 << (hash_value % 8)

    def contains(self, item: str) -> bool:
        for i in range(self.num_hashes):
            hash_value = self._hash(item, i)
            if not (self.bit_array[hash_value // 8] & (1 << (hash_value % 8))):
                return False
        return True

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_num_hashes(self, m: int, n: int) -> int:
        return max(1, int((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        hash_result = hashlib.md5((item + str(seed)).encode()).hexdigest()
        return int(hash_result, 16) % self.num_bits

